class Solution:
    def brightestSpot(self, lamps: List[List[int]]) -> int:
        best, best_at = -1, 0
        for p, r in lamps:
            x = p - r
            lit = sum(1 for q, s in lamps if q - s <= x <= q + s)
            if lit > best or (lit == best and x < best_at):
                best, best_at = lit, x
        return best_at

