class Solution {
    public int brightestSpot(int[][] lamps) {
        int best = -1, bestAt = 0;
        for (int[] a : lamps) {
            int x = a[0] - a[1];
            int lit = 0;
            for (int[] b : lamps) if (b[0] - b[1] <= x && x <= b[0] + b[1]) lit++;
            if (lit > best || (lit == best && x < bestAt)) {
                best = lit;
                bestAt = x;
            }
        }
        return bestAt;
    }
}

