class Solution:
    def brightestSpot(self, lamps: List[List[int]]) -> int:
        starts = sorted(p - r for p, r in lamps)
        stops = sorted(p + r + 1 for p, r in lamps)
        n = len(starts)
        best, best_at, j, i = -1, 0, 0, 0
        while i < n:
            x = starts[i]
            while i + 1 < n and starts[i + 1] == x:
                i += 1
            while j < n and stops[j] <= x:
                j += 1
            lit = (i + 1) - j
            if lit > best:
                best, best_at = lit, x
            i += 1
        return best_at

