class Solution {
    public int brightestSpot(int[][] lamps) {
        int n = lamps.length;
        int[] starts = new int[n], stops = new int[n];
        for (int k = 0; k < n; k++) {
            starts[k] = lamps[k][0] - lamps[k][1];
            stops[k] = lamps[k][0] + lamps[k][1] + 1;
        }
        Arrays.sort(starts);
        Arrays.sort(stops);
        int best = -1, bestAt = 0, j = 0;
        for (int i = 0; i < n; i++) {
            int x = starts[i];
            while (i + 1 < n && starts[i + 1] == x) i++;
            while (j < n && stops[j] <= x) j++;
            int lit = (i + 1) - j;
            if (lit > best) {
                best = lit;
                bestAt = x;
            }
        }
        return bestAt;
    }
}

