static int cmpInt(const void* a, const void* b) {
    int p = *(const int*) a, q = *(const int*) b;
    return (p > q) - (p < q);
}

int brightestSpot(int** lamps, int lampsSize, int* lampsColSize) {
    int n = lampsSize;
    int* starts = malloc(n * sizeof(int));
    int* stops = malloc(n * sizeof(int));
    for (int k = 0; k < n; k++) {
        starts[k] = lamps[k][0] - lamps[k][1];
        stops[k] = lamps[k][0] + lamps[k][1] + 1;
    }
    qsort(starts, n, sizeof(int), cmpInt);
    qsort(stops, n, sizeof(int), cmpInt);
    int best = -1, bestAt = 0, j = 0;
    for (int i = 0; i < n; i++) {
        int x = starts[i];
        while (i + 1 < n && starts[i + 1] == x) i++;
        while (j < n && stops[j] <= x) j++;
        int lit = (i + 1) - j;
        if (lit > best) {
            best = lit;
            bestAt = x;
        }
    }
    free(starts);
    free(stops);
    return bestAt;
}
